  (id1, cn, pinyin, vocabulary, pinyin_vocab, th, sentence_test, translate, pinyin_sentence)
VALUES
-- หน้า 86
(851, '霜', 'shuāng', '霜降', 'shuāng jiàng', 'น้ำค้างแข็ง (เทศกาลซวงเจี้ยง)', '霜降了，天气凉了，该加衣服了。', 'ถึงฤดูน้ำค้างแข็งแล้ว อากาศเย็นลง ควรใส่เสื้อเพิ่ม', 'shuāng jiàng le, tiān qì liáng le, gāi jiā yī fú le'),
(852, '肉', 'ròu', '牛肉', 'niú ròu', 'เนื้อวัว', '那家饭店的牛肉面很好吃。', 'ก๋วยเตี๋ยวเนื้อของร้านอาหารร้านนั้นอร่อยมาก', 'nà jiā fàn diàn de niú ròu miàn hěn hǎo chī'),
(853, '颗', 'kē', '一颗', 'yì kē', 'หนึ่งเม็ด (ลักษณนาม)', '小虫子吃了一颗小豆子。', 'หนอนน้อยกินถั่วไปหนึ่งเม็ด', 'xiǎo chóng zi chī le yì kē xiǎo dòu zi'),
(854, '采', 'cǎi', '采花', 'cǎi huā', 'เก็บดอกไม้', '一只小兔子去山里采花了。', 'กระต่ายน้อยตัวหนึ่งไปเก็บดอกไม้ในภูเขา', 'yì zhī xiǎo tù zi qù shān lǐ cǎi huā le'),
(855, '取', 'qǔ', '取出', 'qǔ chū', 'หยิบออกมา', '黑熊从洞里取出蜂蜜来分给了大家。', 'หมีดำหยิบน้ำผึ้งออกมาจากโพรงแบ่งให้ทุกคน', 'hēi xióng cóng dòng lǐ qǔ chū fēng mì lái fēn gěi le dà jiā'),
(856, '玩', 'wán', '玩耍', 'wán shuǎ', 'เล่นสนุก', '小王子和朋友们在一起玩耍。', 'เจ้าชายน้อยเล่นสนุกอยู่กับเพื่อนๆ', 'xiǎo wáng zǐ hé péng yǒu men zài yì qǐ wán shuǎ'),
(857, '算', 'suàn', '算术', 'suàn shù', 'เลขคณิต', '古时候，人们用算盘作为算术工具。', 'สมัยโบราณ ผู้คนใช้ลูกคิดเป็นเครื่องมือคำนวณ', 'gǔ shí hòu, rén men yòng suàn pán zuò wéi suàn shù gōng jù'),
(858, '照', 'zhào', '照耀', 'zhào yào', 'สาดส่อง', '花儿在阳光的照耀下更美丽了。', 'ดอกไม้ยิ่งงดงามภายใต้แสงอาทิตย์ที่สาดส่อง', 'huā ér zài yáng guāng de zhào yào xià gèng měi lì le'),
(859, '纯', 'chún', '纯色', 'chún sè', 'สีล้วน/สีเรียบ', '这件衣服太花了，我更喜欢纯色的。', 'เสื้อตัวนี้ลายเยอะไป ฉันชอบแบบสีเรียบมากกว่า', 'zhè jiàn yī fú tài huā le, wǒ gèng xǐ huān chún sè de'),
(860, '耍', 'shuǎ', '玩耍', 'wán shuǎ', 'เล่นสนุก', '长胡子老爷爷在和孩子们一起玩耍。', 'คุณปู่หนวดยาวกำลังเล่นสนุกอยู่กับเด็กๆ', 'cháng hú zi lǎo yé ye zài hé hái zi men yì qǐ wán shuǎ'),
-- หน้า 87
(861, '趣', 'qù', '有趣', 'yǒu qù', 'น่าสนใจ/สนุก', '动画片很有趣，我想多看一会儿。', 'การ์ตูนสนุกมาก ฉันอยากดูต่ออีกสักหน่อย', 'dòng huà piàn hěn yǒu qù, wǒ xiǎng duō kàn yí huì ér'),
(862, '懂', 'dǒng', '懂得', 'dǒng de', 'เข้าใจ/รู้', '爸爸妈妈教我懂得了很多道理。', 'พ่อแม่สอนให้ฉันเข้าใจเหตุผลหลายอย่าง', 'bà ba mā mā jiào wǒ dǒng de le hěn duō dào lǐ'),
(863, '捧', 'pěng', '捧着', 'pěng zhe', 'ประคอง/ถือ (สองมือ)', '爷爷捧着那张报纸看了很长时间。', 'คุณปู่ถือหนังสือพิมพ์อ่านอยู่นานมาก', 'yé ye pěng zhe nà zhāng bào zhǐ kàn le hěn cháng shí jiān'),
(864, '寸', 'cùn', '一寸', 'yì cùn', 'หนึ่งชุ่น (หน่วยวัดจีน)', '一只毛毛虫大约有一寸长。', 'หนอนผีเสื้อตัวหนึ่งยาวประมาณหนึ่งชุ่น', 'yì zhī máo mao chóng dà yuē yǒu yí cùn cháng'),
(865, '习', 'xí', '练习', 'liàn xí', 'ฝึกฝน', '他游泳游得不好，正在努力练习。', 'เขาว่ายน้ำไม่เก่ง กำลังตั้งใจฝึกฝนอยู่', 'tā yóu yǒng yóu de bù hǎo, zhèng zài nǔ lì liàn xí'),
(866, '合', 'hé', '合唱', 'hé chàng', 'ร้องประสานเสียง', '小朋友们合唱了很多好听的歌。', 'เด็กๆ ร้องประสานเสียงเพลงเพราะๆ หลายเพลง', 'xiǎo péng yǒu men hé chàng le hěn duō hǎo tīng de gē'),
(867, '记', 'jì', '日记', 'rì jì', 'ไดอารี่/บันทึกประจำวัน', '老师让我们每天记日记。', 'คุณครูให้เราเขียนไดอารี่ทุกวัน', 'lǎo shī ràng wǒ men měi tiān jì rì jì'),
(868, '阴', 'yīn', '阴天', 'yīn tiān', 'วันที่ฟ้าครึ้ม', '晚上阴天了，月亮藏在了乌云后面。', 'ตอนกลางคืนฟ้าครึ้ม พระจันทร์ซ่อนอยู่หลังเมฆดำ', 'wǎn shàng yīn tiān le, yuè liàng cáng zài le wū yún hòu miàn'),
(869, '情', 'qíng', '心情', 'xīn qíng', 'อารมณ์/ความรู้สึก', '今天天气真好，大家的心情也很好。', 'วันนี้อากาศดีมาก อารมณ์ของทุกคนก็ดีตามไปด้วย', 'jīn tiān tiān qì zhēn hǎo, dà jiā de xīn qíng yě hěn hǎo'),
(870, '必', 'bì', '必须', 'bì xū', 'จำเป็นต้อง/ต้อง', '重要的事情必须记在心里。', 'เรื่องสำคัญต้องจดจำไว้ในใจ', 'zhòng yào de shì qíng bì xū jì zài xīn lǐ'),
-- หน้า 88
(871, '顾', 'gù', '照顾', 'zhào gù', 'ดูแล', '园丁精心照顾着花园里的花草树木。', 'คนสวนดูแลต้นไม้ดอกไม้ในสวนอย่างพิถีพิถัน', 'yuán dīng jīng xīn zhào gù zhe huā yuán lǐ de huā cǎo shù mù'),
(872, '归', 'guī', '归来', 'guī lái', 'กลับมา', '小船从远方归来，就要靠岸了。', 'เรือน้อยแล่นกลับมาจากแดนไกล กำลังจะเทียบฝั่ง', 'xiǎo chuán cóng yuǎn fāng guī lái, jiù yào kào àn le'),
(873, '件', 'jiàn', '一件事', 'yí jiàn shì', 'เรื่องหนึ่ง (ลักษณนาม)', '读书是最让我快乐的一件事。', 'การอ่านหนังสือเป็นเรื่องที่ทำให้ฉันมีความสุขที่สุด', 'dú shū shì zuì ràng wǒ kuài lè de yí jiàn shì'),
(874, '孩', 'hái', '孩子', 'hái zi', 'เด็ก/ลูก', '每个父母都很关心自己的孩子。', 'พ่อแม่ทุกคนต่างห่วงใยลูกของตัวเอง', 'měi gè fù mǔ dōu hěn guān xīn zì jǐ de hái zi'),
(875, '专', 'zhuān', '专心', 'zhuān xīn', 'ตั้งใจ/มีสมาธิ', '他正坐在桌子旁边专心学习。', 'เขากำลังนั่งอยู่ข้างโต๊ะตั้งใจเรียนหนังสือ', 'tā zhèng zuò zài zhuō zi páng biān zhuān xīn xué xí'),
(876, '渐', 'jiàn', '渐渐', 'jiàn jiàn', 'ค่อยๆ/ทีละน้อย', '秋天来了，白天渐渐变短了。', 'ฤดูใบไม้ร่วงมาถึง กลางวันค่อยๆ สั้นลง', 'qiū tiān lái le, bái tiān jiàn jiàn biàn duǎn le'),
(877, '泪', 'lèi', '眼泪', 'yǎn lèi', 'น้ำตา', '国歌声中，运动员流下了激动的眼泪。', 'ในเสียงเพลงชาติ นักกีฬาหลั่งน้ำตาด้วยความตื้นตัน', 'guó gē shēng zhōng, yùn dòng yuán liú xià le jī dòng de yǎn lèi'),
(878, '整', 'zhěng', '整齐', 'zhěng qí', 'เป็นระเบียบ', '我们要把自己的物品摆放整齐。', 'เราต้องจัดวางของของตัวเองให้เป็นระเบียบ', 'wǒ men yào bǎ zì jǐ de wù pǐn bǎi fàng zhěng qí'),
(879, '请', 'qǐng', '请坐', 'qǐng zuò', 'เชิญนั่ง', '欢迎你来我家，先请坐吧！', 'ยินดีต้อนรับสู่บ้านฉัน เชิญนั่งก่อนเลย!', 'huān yíng nǐ lái wǒ jiā, xiān qǐng zuò ba'),
(880, '惜', 'xī', '可惜', 'kě xī', 'น่าเสียดาย', '那么多水果都坏了，太可惜了！', 'ผลไม้ตั้งมากมายเน่าหมดเลย น่าเสียดายจริงๆ!', 'nà me duō shuǐ guǒ dōu huài le, tài kě xī le'),
-- หน้า 89
(881, '尊', 'zūn', '尊敬', 'zūn jìng', 'เคารพ', '学生要尊敬老师，老师要关爱学生。', 'นักเรียนต้องเคารพครู ครูต้องเอ็นดูนักเรียน', 'xué shēng yào zūn jìng lǎo shī, lǎo shī yào guān ài xué shēng'),
(882, '界', 'jiè', '分界', 'fēn jiè', 'เส้นแบ่งเขต', '两个人因为田地的分界线吵了起来。', 'สองคนทะเลาะกันเพราะเส้นแบ่งเขตที่นา', 'liǎng gè rén yīn wèi tián dì de fēn jiè xiàn chǎo le qǐ lái'),
(883, '桥', 'qiáo', '大桥', 'dà qiáo', 'สะพานใหญ่', '南京长江大桥是一座有名的桥。', 'สะพานข้ามแม่น้ำแยงซีเมืองหนานจิงเป็นสะพานที่มีชื่อเสียง', 'nán jīng cháng jiāng dà qiáo shì yí zuò yǒu míng de qiáo'),
(884, '句', 'jù', '句子', 'jù zi', 'ประโยค', '今天，我学会了一个有用的句子。', 'วันนี้ ฉันได้เรียนรู้ประโยคที่มีประโยชน์หนึ่งประโยค', 'jīn tiān, wǒ xué huì le yí gè yǒu yòng de jù zi'),
(885, '读', 'dú', '读书', 'dú shū', 'อ่านหนังสือ', '读书时，他常常会做读书笔记。', 'เวลาอ่านหนังสือ เขามักจะจดบันทึกการอ่าน', 'dú shū shí, tā cháng cháng huì zuò dú shū bǐ jì'),
(886, '短', 'duǎn', '长短', 'cháng duǎn', 'ความยาว (สั้น-ยาว)', '这件衣服长短不合适。', 'เสื้อตัวนี้ความยาวไม่พอดี', 'zhè jiàn yī fú cháng duǎn bù hé shì'),
(887, '轰', 'hōng', '轰隆隆', 'hōng lóng lóng', 'เสียงกึกก้อง (ฟ้าร้อง)', '一道闪电过后，接着是轰隆隆的雷声。', 'หลังฟ้าแลบแวบหนึ่ง ตามมาด้วยเสียงฟ้าร้องกึกก้อง', 'yí dào shǎn diàn guò hòu, jiē zhe shì hōng lóng lóng de léi shēng'),
(888, '复', 'fù', '复习', 'fù xí', 'ทบทวน', '学习新知识前，我们先复习一下。', 'ก่อนเรียนความรู้ใหม่ เรามาทบทวนกันก่อน', 'xué xí xīn zhī shí qián, wǒ men xiān fù xí yí xià'),
(889, '童', 'tóng', '儿童', 'ér tóng', 'เด็ก', '六一儿童节是全国儿童的节日。', 'วันเด็ก 1 มิถุนายนเป็นวันของเด็กทั่วประเทศ', 'liù yī ér tóng jié shì quán guó ér tóng de jié rì'),
(890, '双', 'shuāng', '一双', 'yì shuāng', 'หนึ่งคู่', '我有一双小小手，一共十个手指头。', 'ฉันมีมือน้อยๆ หนึ่งคู่ รวมทั้งหมดสิบนิ้ว', 'wǒ yǒu yì shuāng xiǎo xiǎo shǒu, yí gòng shí gè shǒu zhǐ tou'),
-- หน้า 90
(891, '轻', 'qīng', '轻松', 'qīng sōng', 'สบาย/ผ่อนคลาย', '工作做完了，一下子轻松了许多。', 'ทำงานเสร็จแล้ว รู้สึกผ่อนคลายขึ้นมากทันที', 'gōng zuò zuò wán le, yí xià zi qīng sōng le xǔ duō'),
(892, '泼', 'pō', '泼水', 'pō shuǐ', 'สาดน้ำ', '泼水节是一个非常有趣的节日。', 'เทศกาลสาดน้ำ (สงกรานต์) เป็นเทศกาลที่สนุกมาก', 'pō shuǐ jié shì yí gè fēi cháng yǒu qù de jié rì'),
(893, '躺', 'tǎng', '躺下', 'tǎng xià', 'นอนลง', '他实在太困了，一躺下就睡了。', 'เขาง่วงมากจริงๆ พอนอนลงก็หลับเลย', 'tā shí zài tài kùn le, yì tǎng xià jiù shuì le'),
(894, '柔', 'róu', '柔软', 'róu ruǎn', 'นุ่มนวล/อ่อนนุ่ม', '风儿吹着她柔软的秀发，真美！', 'สายลมพัดผมนุ่มสลวยของเธอ สวยจริงๆ!', 'fēng ér chuī zhe tā róu ruǎn de xiù fà, zhēn měi'),
(895, '龄', 'líng', '年龄', 'nián líng', 'อายุ', '六岁是大多数小朋友的入学年龄。', 'หกขวบคืออายุเข้าเรียนของเด็กส่วนใหญ่', 'liù suì shì dà duō shù xiǎo péng yǒu de rù xué nián líng'),
(896, '赞', 'zàn', '赞扬', 'zàn yáng', 'ชื่นชม/ยกย่อง', '他的表现得到了大家的赞扬。', 'การแสดงออกของเขาได้รับคำชื่นชมจากทุกคน', 'tā de biǎo xiàn dé dào le dà jiā de zàn yáng'),
(897, '虚', 'xū', '虚心', 'xū xīn', 'ถ่อมตัว/ใจกว้างรับฟัง', '遇到不懂的问题要虚心请教。', 'เจอปัญหาที่ไม่เข้าใจต้องถ่อมตัวสอบถาม', 'yù dào bù dǒng de wèn tí yào xū xīn qǐng jiào'),
(898, '垂', 'chuí', '低垂', 'dī chuí', 'ห้อยต่ำ/ลู่ลง', '天气太热，树上的叶子低垂下来。', 'อากาศร้อนมาก ใบไม้บนต้นห้อยลู่ลงมา', 'tiān qì tài rè, shù shàng de yè zi dī chuí xià lái'),
(899, '展', 'zhǎn', '展开', 'zhǎn kāi', 'คลี่ออก/กางออก', '把洗好的衣服展开晒，这样干得快。', 'เอาเสื้อผ้าที่ซักแล้วคลี่ออกตาก จะได้แห้งเร็ว', 'bǎ xǐ hǎo de yī fú zhǎn kāi shài, zhè yàng gàn de kuài'),
(900, '勾', 'gōu', '拉勾', 'lā gōu', 'เกี่ยวก้อย (สัญญา)', '我们拉勾了，就不能变了。', 'เราเกี่ยวก้อยสัญญากันแล้ว ห้ามเปลี่ยนใจนะ', 'wǒ men lā gōu le, jiù bù néng biàn le');
